From 024af955d2d31517b1242395be9be1196e897746 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:33:58 +0100
Subject: [PATCH] containments/desktop: scroll the rename field by whole lines

The rename field was not a whole number of lines tall and the wheel
moved it by a fixed amount of pixels, so half lines showed and lines
could be skipped. Size it to whole lines and scroll by whole lines too.

BUG: 523491
---
 .../package/contents/ui/RenameEditor.qml      | 23 ++++++++++++++++++-
 1 file changed, 22 insertions(+), 1 deletion(-)

diff --git a/containments/desktop/package/contents/ui/RenameEditor.qml b/containments/desktop/package/contents/ui/RenameEditor.qml
index bc65b7f1b1..0e3af9fd37 100644
--- a/containments/desktop/package/contents/ui/RenameEditor.qml
+++ b/containments/desktop/package/contents/ui/RenameEditor.qml
@@ -56,6 +56,27 @@ PlasmaComponents.ScrollView {
         }

         property FolderItemDelegate targetItem: null
+        readonly property real lineHeight: lineCount > 0 ? contentHeight / lineCount : 0
+        property real wheelLines: 0
+
+        // Scroll by whole lines, so that no line is ever cut in half;
+        // stacked above the WheelHandler of the ScrollView
+        MouseArea {
+            parent: root.contentItem
+            anchors.fill: parent
+            z: 1
+            enabled: root.PlasmaComponents.ScrollBar.vertical.policy === Qt.ScrollBarAlwaysOn
+            acceptedButtons: Qt.NoButton
+
+            onWheel: wheel => {
+                const flickable = root.contentItem;
+                editor.wheelLines += wheel.angleDelta.y / 120 * Application.styleHints.wheelScrollLines;
+                const lines = Math.trunc(editor.wheelLines);
+                editor.wheelLines -= lines;
+                const line = Math.round(flickable.contentY / editor.lineHeight) - lines;
+                flickable.contentY = Math.max(0, Math.min(line * editor.lineHeight, flickable.contentHeight - flickable.height));
+            }
+        }

         Binding {
             target: editor.background
@@ -168,7 +189,7 @@ PlasmaComponents.ScrollView {
                 _height = targetItem.labelArea.height + editor.topPadding + editor.bottomPadding;
             } else {
                 var realHeight = contentHeight + editor.topPadding + editor.bottomPadding;
-                var maxHeight = Kirigami.Units.iconSizes.sizeForLabels * (Plasmoid.configuration.textLines + 1) + editor.topPadding + editor.bottomPadding;
+                var maxHeight = lineHeight * (Plasmoid.configuration.textLines + 1) + editor.topPadding + editor.bottomPadding;
                 _height = Math.min(realHeight, maxHeight);
             }
             return _height + (addWidthHoriozontalScroller ? root.PlasmaComponents.ScrollBar.horizontal.height : 0);
-- 
